    id: 'sql-e13',
    title: 'Total Medication Coverage Days per Patient',
    company: 'CVS Health',
    companyDomain: 'cvshealth.com',
    alsoAskedAt: ['Zocdoc', 'UnitedHealth', 'Teladoc', 'Practo', 'Optum', 'Humana'],
