    hintSteps: [
      { text: 'Consider the relationship between disputes and transactions. Ensure that the join condition correctly links disputed transactions to their associated accounts.', starterCode: 'SELECT a.account_id, a.user_id, a.account_type, SUM(d.amount) AS total_disputed\nFROM disputes d\nJOIN transactions t ON d.txn_id = t.txn_id\nJOIN accounts a ON t.account_id = a.account_id\nGROUP BY a.account_id, a.user_id, a.account_type' },
      { text: 'Verify that the join keys between disputes, transactions, and accounts are accurate. The issue might be in how these tables are connected.', starterCode: 'SELECT a.account_id, a.user_id, a.account_type, SUM(d.amount) AS total_disputed\nFROM disputes d\nJOIN transactions t ON d.txn_id = t.txn_id\nJOIN accounts a ON t.account_id = a.account_id\nGROUP BY a.account_id, a.user_id, a.account_type' }
    ],
