        detectionSignature: { mustMatch: ['/like\\s*\'%t\\.co%\'/i', '/like\\s*\'%www\\.google\\.com%\'/i'], mustNotMatch: ['/substr\\s*\\(/i', '/group\\s+by\\s+referrer_url\\b/i'], note: 'hand-classifies domains with substring LIKE, which both hardcodes the list and over-matches unrelated hosts' },
        tradeoff: 'Reads simply and credits the big channels by name, so it looks like a deliberate, clean classification.',
